import{_ as t,o,c as a,ae as i}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"iCost Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/08-icost-bill-import-guide.md","filePath":"v1/en/guide/08-icost-bill-import-guide.md"}'),r={name:"v1/en/guide/08-icost-bill-import-guide.md"};function l(s,e,n,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="icost-bill-import-guide" tabindex="-1">iCost Bill Import Guide <a class="header-anchor" href="#icost-bill-import-guide" aria-label="Permalink to &quot;iCost Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide shows how to export bills from <strong>iCost</strong> and import them into <strong>Expense Tracker: Koala</strong> (“Koala”).</p><p>Expense Tracker: Koala (“Koala”) supports <strong>iCost Excel export</strong> (<code>.xlsx</code> or <code>.xls</code>). CSV exported from iCost is not supported.</p><hr><h2 id="📱-part-1-export-in-icost" tabindex="-1">📱 Part 1: Export in iCost <a class="header-anchor" href="#📱-part-1-export-in-icost" aria-label="Permalink to &quot;📱 Part 1: Export in iCost&quot;">​</a></h2><p>Menu names may differ across versions:</p><ol><li>Open iCost</li><li>Go to <strong>Settings / More</strong></li><li>Find <strong>Export / Data export / Export bills</strong></li><li>Choose <strong>Excel (.xlsx / .xls)</strong></li><li>Choose a date range (recommended up to 3 months)</li><li>Export and save the file</li></ol><blockquote><p>⚠️ Important: If you export as CSV, Koala will show a message that CSV is not supported.</p></blockquote><hr><h2 id="📱-part-2-import-into-expense-tracker-koala" tabindex="-1">📱 Part 2: Import into Expense Tracker: Koala <a class="header-anchor" href="#📱-part-2-import-into-expense-tracker-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Expense Tracker: Koala&quot;">​</a></h2><h3 id="step-1-open-the-import-page" tabindex="-1">Step 1: Open the import page <a class="header-anchor" href="#step-1-open-the-import-page" aria-label="Permalink to &quot;Step 1: Open the import page&quot;">​</a></h3><ol><li>Open Expense Tracker: Koala</li><li>Tap <strong>Settings</strong></li><li>Find <strong>Bill Import</strong></li><li>Enter the bill import page</li></ol><h3 id="step-2-choose-the-import-source" tabindex="-1">Step 2: Choose the import source <a class="header-anchor" href="#step-2-choose-the-import-source" aria-label="Permalink to &quot;Step 2: Choose the import source&quot;">​</a></h3><ol><li>Tap <strong>Import source</strong></li><li>Select <strong>iCost</strong></li></ol><blockquote><p>⚠️ Important: You must choose <strong>iCost</strong>, otherwise Koala may parse it as another source and fail to find the header or shift fields.</p></blockquote><h3 id="step-3-pick-the-file" tabindex="-1">Step 3: Pick the file <a class="header-anchor" href="#step-3-pick-the-file" aria-label="Permalink to &quot;Step 3: Pick the file&quot;">​</a></h3><ol><li>Tap <strong>File path</strong></li><li>Select the Excel file exported from iCost (<code>.xlsx</code> / <code>.xls</code>)</li><li>Confirm the file name is shown</li></ol><h3 id="step-4-link-a-ledger" tabindex="-1">Step 4: Link a ledger <a class="header-anchor" href="#step-4-link-a-ledger" aria-label="Permalink to &quot;Step 4: Link a ledger&quot;">​</a></h3><ol><li>Tap <strong>Linked ledger</strong></li><li>Choose the target ledger</li></ol><h3 id="step-5-parse-and-preview" tabindex="-1">Step 5: Parse and preview <a class="header-anchor" href="#step-5-parse-and-preview" aria-label="Permalink to &quot;Step 5: Parse and preview&quot;">​</a></h3><ol><li>Tap <strong>Parse</strong> (top-right)</li><li>After parsing succeeds, Koala opens the preview page</li><li>You can edit category, account, time, amount, tags, and notes before importing</li></ol><h3 id="step-6-import" tabindex="-1">Step 6: Import <a class="header-anchor" href="#step-6-import" aria-label="Permalink to &quot;Step 6: Import&quot;">​</a></h3><ol><li>Tap <strong>Import</strong> after confirming everything looks correct</li><li>Wait for import to finish</li></ol><hr><h2 id="📋-icost-excel-format-how-koala-reads-it" tabindex="-1">📋 iCost Excel format (how Koala reads it) <a class="header-anchor" href="#📋-icost-excel-format-how-koala-reads-it" aria-label="Permalink to &quot;📋 iCost Excel format (how Koala reads it)&quot;">​</a></h2><p>Koala checks:</p><ul><li>The Excel file has a readable worksheet</li><li>The header row contains <strong>&quot;日期&quot;</strong> (used to locate the header)</li></ul><p>Tip: If iCost lets you choose export language, export with Chinese headers (at least keep &quot;日期&quot;).</p><h3 id="columns-by-position" tabindex="-1">Columns (by position) <a class="header-anchor" href="#columns-by-position" aria-label="Permalink to &quot;Columns (by position)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>Date</td><td>Date strings (multiple formats) or Excel serial date</td></tr><tr><td>2</td><td>Type</td><td>Must contain the keyword for expense or income</td></tr><tr><td>3</td><td>Amount</td><td><code>+</code> or <code>-</code> allowed; thousands separators are handled</td></tr><tr><td>4</td><td>Parent category</td><td>Used to match Koala categories</td></tr><tr><td>5</td><td>Child category</td><td>If empty, Koala uses parent category</td></tr><tr><td>6</td><td>Account</td><td>If empty, Koala uses a default account</td></tr><tr><td>8</td><td>Note</td><td>Text</td></tr><tr><td>9</td><td>Currency code</td><td>For example <code>CNY</code> or <code>USD</code> (fallback to ledger default)</td></tr><tr><td>10</td><td>Tags</td><td>Comma-separated (<code>,</code> or <code>，</code>)</td></tr></tbody></table><h3 id="field-mapping-how-koala-imports" tabindex="-1">Field mapping (how Koala imports) <a class="header-anchor" href="#field-mapping-how-koala-imports" aria-label="Permalink to &quot;Field mapping (how Koala imports)&quot;">​</a></h3><ul><li>Date (row[0]) → bill date</li><li>Type (row[1], contains expense/income keyword) → bill type</li><li>Amount (row[2]) → amount</li><li>Parent category (row[3]) → parent category (matched/created)</li><li>Child category (row[4]; if empty, use parent) → child category (matched/created)</li><li>Account (row[5]; if empty, default account) → account</li><li>Column 7 (row[6]) → ignored</li><li>Note (row[7]) → note</li><li>Currency code (row[8]) → currency (matched by code; fallback to ledger currency)</li><li>Tags (row[9]) → tags (matched/created and linked)</li></ul><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><ol><li><strong>Excel only</strong>: iCost CSV files cannot be imported.</li><li><strong>No automatic deduplication</strong>: Importing the same file twice will create duplicate bills. Avoid importing the same time range repeatedly.</li><li><strong>Header language</strong>: Parsing relies on finding a header row that contains “日期”. If you export with non-Chinese headers, Koala may fail to locate the header.</li><li><strong>Empty account handling</strong>: If the account column is empty, Koala uses a default account as a fallback. Consider filling in accounts in iCost, or batch-edit accounts in the preview page.</li><li><strong>Category matching</strong>: Koala matches by “parent + child” names. If matching fails, the preview page will show it as incomplete; select the correct category before importing.</li></ol><hr><h2 id="🔧-faq" tabindex="-1">🔧 FAQ <a class="header-anchor" href="#🔧-faq" aria-label="Permalink to &quot;🔧 FAQ&quot;">​</a></h2><h3 id="q1-icost-header-not-found" tabindex="-1">Q1: “iCost header not found”. <a class="header-anchor" href="#q1-icost-header-not-found" aria-label="Permalink to &quot;Q1: “iCost header not found”.&quot;">​</a></h3><p>Common reasons:</p><ol><li>The header row does not contain “日期” (for example, exported with English headers)</li><li>The file is not an iCost export, or it was edited and the structure changed</li><li>The Excel file is empty or has no worksheet</li></ol><p>Re-export from iCost and prefer Chinese headers.</p><h3 id="q2-many-records-went-into-the-same-account" tabindex="-1">Q2: Many records went into the same account. <a class="header-anchor" href="#q2-many-records-went-into-the-same-account" aria-label="Permalink to &quot;Q2: Many records went into the same account.&quot;">​</a></h3><p>This is expected if the “Account” column is empty. Koala uses a default account as a fallback. Batch-edit accounts in the preview page, or export again after filling accounts in iCost.</p><h3 id="q3-categories-don-t-match" tabindex="-1">Q3: Categories don’t match. <a class="header-anchor" href="#q3-categories-don-t-match" aria-label="Permalink to &quot;Q3: Categories don’t match.&quot;">​</a></h3><p>On the preview page, tap a record and select the correct category manually; or create categories in Koala with the same names as in the iCost export, then parse again.</p><hr><h2 id="📚-related-guides" tabindex="-1">📚 Related Guides <a class="header-anchor" href="#📚-related-guides" aria-label="Permalink to &quot;📚 Related Guides&quot;">​</a></h2><ul><li><a href="./01-template-bill-import-guide">Template Bill Import (CSV)</a></li><li><a href="./02-wechat-bill-import-guide">WeChat Bill Import</a></li><li><a href="./03-alipay-bill-import-guide">Alipay Bill Import</a></li><li><a href="./07-pixiu-bill-import-guide">Pixiu Bill Import</a></li><li><a href="./04-multi-ledger-guide">Multi-ledger</a></li></ul><hr><p><strong>Last updated</strong>: Apr 2026</p>',51)])])}const u=t(r,[["render",l]]);export{m as __pageData,u as default};
